class Cart:
    def __init__(self, free_shipping_threshold: float = 100.0, shipping_cost: float = 15.0) -> None:
        self.free_shipping_threshold = free_shipping_threshold
        self.shipping_cost = shipping_cost
        self._items = []  # list of (name, unit_price, quantity)
        self._discounts = []
        self._vouchers = []
        self._item_total = 0.0

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        self._items.append((name, unit_price, quantity))
        self._item_total += unit_price * quantity

    def apply_discount(self, percent: float) -> None:
        self._discounts.append(percent)

    def apply_voucher(self, amount: float) -> None:
        self._vouchers.append(amount)

    def total(self) -> float:
        items_total = self._item_total

        # Best single discount (as amount saved) vs best voucher (value capped at items_total)
        best_saving = 0.0
        for pct in self._discounts:
            saving = items_total * (pct / 100.0)
            if saving > best_saving:
                best_saving = saving
        for amt in self._vouchers:
            saving = min(amt, items_total)
            if saving > best_saving:
                best_saving = saving

        items_after = max(0.0, items_total - best_saving)

        # Shipping based on pre-discount item value
        if items_total >= self.free_shipping_threshold:
            shipping = 0.0
        else:
            shipping = self.shipping_cost

        return round(items_after + shipping, 2)
